(function() {
  const slider = document.getElementById('relay-slider');
  const nVal = document.getElementById('n-val');
  const statesVal = document.getElementById('states-val');
  const bitsVal = document.getElementById('bits-val');
  const canvas = document.getElementById('growth-chart');
  const ctx = canvas.getContext('2d');

  // Handle High DPI displays
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);

  const width = rect.width;
  const height = rect.height;
  const padding = 30;

  function drawChart(currentN) {
    ctx.clearRect(0, 0, width, height);

    // Axes
    ctx.beginPath();
    ctx.strokeStyle = '#ccc';
    ctx.lineWidth = 1;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Labels
    ctx.fillStyle = '#666';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Relay Count (n)', width / 2, height - 5);
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('Value', 0, 0);
    ctx.restore();

    // Data Generation
    const maxN = 10;
    const maxStates = Math.pow(2, maxN);
    const maxBits = maxN;

    // Scale factors
    // We need to fit both linear (max 10) and exponential (max 1024) on same chart
    // To make it visible, we might need a log scale for Y or just show the divergence clearly
    // Let's use a linear scale but cap the visual height for states to show it goes 'off chart' or normalize
    // Actually, standard pedagogy shows them diverging. Let's normalize States to fit height, and Bits to fit height.

    const xStep = (width - 2 * padding) / maxN;

    // Draw States Curve (Exponential)
    ctx.beginPath();
    ctx.strokeStyle = '#d9534f'; // Red
    ctx.lineWidth = 2;
    for (let n = 0; n <= maxN; n++) {
      const val = Math.pow(2, n);
      const normalizedVal = val / maxStates; // 0 to 1
      const x = padding + n * xStep;
      const y = height - padding - (normalizedVal * (height - 2 * padding));
      if (n === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw Bits Line (Linear)
    ctx.beginPath();
    ctx.strokeStyle = '#007acc'; // Blue
    ctx.lineWidth = 2;
    for (let n = 0; n <= maxN; n++) {
      const val = n;
      const normalizedVal = val / maxBits; // 0 to 1
      const x = padding + n * xStep;
      const y = height - padding - (normalizedVal * (height - 2 * padding));
      if (n === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw Current Point
    const currX = padding + currentN * xStep;
    const currStatesY = height - padding - ((Math.pow(2, currentN) / maxStates) * (height - 2 * padding));
    const currBitsY = height - padding - ((currentN / maxBits) * (height - 2 * padding));

    // Dot for States
    ctx.fillStyle = '#d9534f';
    ctx.beginPath();
    ctx.arc(currX, currStatesY, 4, 0, Math.PI * 2);
    ctx.fill();

    // Dot for Bits
    ctx.fillStyle = '#007acc';
    ctx.beginPath();
    ctx.arc(currX, currBitsY, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  function updateDisplay() {
    const n = parseInt(slider.value, 10);
    const states = Math.pow(2, n);

    nVal.textContent = n;
    statesVal.textContent = states.toLocaleString();
    bitsVal.textContent = n;

    drawChart(n);
  }

  slider.addEventListener('input', updateDisplay);

  // Initial draw
  updateDisplay();

  // Resize handler
  window.addEventListener('resize', () => {
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    updateDisplay();
  });
})();
